target.css:
:root {
  --label-bg: #f9f3e8;
  --label-border: #b08050;
  --header-bg: #7a5230;
  --header-text: #f9f3e8;
  --soap-name: #3d2108;
  --subtitle: #7a5230;
  --ingredient-dot: #b08050;
  --ingredient-text: #4a3010;
  --footer-bg: #ede0c8;
  --footer-text: #7a5230;
  --divider: #b08050;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.soap-label {
  background-color: var(--label-bg);
  border: 3px solid var(--label-border);
  border-radius: 10px;
  width: 260px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.label-header {
  background-color: var(--header-bg);
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 0;
}

.label-no {
  color: var(--header-text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.batch-id {
  color: var(--header-text);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.soap-name {
  color: var(--soap-name);
  font-size: 22px;
  font-weight: 800;
  margin: 16px 0 4px;
  letter-spacing: 0.02em;
  text-align: center;
}

.soap-subtitle {
  color: var(--subtitle);
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin: 0 0 14px;
}

.ingredients {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
}

.ingredients li {
  color: var(--ingredient-text);
  font-size: 13px;
  font-weight: 500;
  padding-left: 14px;
  position: relative;
}

.ingredients li::before {
  content: "✦";
  color: var(--ingredient-dot);
  font-size: 9px;
  position: absolute;
  left: 0;
  top: 2px;
}

.label-footer {
  background-color: var(--footer-bg);
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 0;
}

.weight {
  color: var(--footer-text);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
}

.divider {
  color: var(--divider);
  font-size: 14px;
  font-weight: 700;
}

.cure-date {
  color: var(--footer-text);
  font-size: 12px;
  font-weight: 500;
}

